/* @autogenerated */
import { computed, effect, inject, Injectable, Injector, signal, untracked } from '@angular/core';
import {
  combineLatest,
  distinctUntilChanged,
  firstValueFrom,
  lastValueFrom,
  map,
  Observable,
  of,
  Subject,
  switchMap,
  timeout,
} from 'rxjs';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import type { RepositoryProvider } from '../repository/provider/repository-provider.interface';
import type { RepositoryMetadata } from '../repository/repository.service';
import { OfflineDb } from './offline-db';
import { compact, dependentsOf, entityId, replaceValue, sorted } from './offline-ops';
import {
  isNetworkError,
  OFFLINE_FILE_PREFIX,
  OFFLINE_DB_NAME,
  OFFLINE_REPOSITORIES,
  OfflineError,
  offlineError,
  OfflineOp,
  OfflineRunState,
  OfflineShadow,
  OfflineSyncState,
} from './offline.model';
import { OfflineProvider } from './offline-provider';

/** Tiempo máximo de una operación al sincronizar; pasado, se trata como falta de conexión. */
const OP_TIMEOUT = 60_000;
const FILE_TIMEOUT = 300_000;

/** Lecturas guardadas que se conservan para consultar sin conexión. */
const READS_TTL = 30 * 24 * 3600_000;

/** Estado HTTP de sesión caducada: no es un fallo de la operación sino de la sesión. */
const UNAUTHORIZED = 401;

const NOT_FOUND = 404;

/** Tras un fallo de red, tiempo hasta volver a intentar llegar al servidor. */
const RETRY_ONLINE = 20_000;

/** Espera por defecto (ms) con la conexión estable antes de subir los cambios sola (`data.offline-sync-delay`). */
export const DEFAULT_AUTO_SYNC_DELAY = 30_000;

/** Espera máxima entre intentos automáticos cuando la red se sigue cortando. */
const MAX_AUTO_SYNC_DELAY = 10 * 60_000;

/**
 * Cómo sigue la sincronización:
 * - `retry`: reintenta también las fallidas y bloqueadas; para en el primer error.
 * - `skip`: deja las fallidas (y lo que depende de ellas) y sigue con el resto.
 * - `auto`: la que se lanza sola al volver la conexión; sube solo lo pendiente y para en el primer error.
 */
export type OfflineSyncMode = 'retry' | 'skip' | 'auto';

/** Provider real de un repositorio, para subir sus operaciones. */
interface Registered {
  raw: RepositoryProvider<any, any>;
  key: string;
}

/** Operación aplicada en el servidor: los repositorios refrescan su caché. */
export interface OfflineApplied {
  repo: string;
  key: string;
}

/**
 * Cola de escrituras sin conexión (`data.offline: true`). Los providers de los repositorios se envuelven con
 * {@link OfflineProvider}: si no hay red, o ya hay cambios pendientes (para no alterar el orden), las escrituras se
 * guardan en IndexedDB y la entidad se sirve desde su copia local hasta que se sube.
 *
 * La subida ({@link sync}) va operación a operación, por orden. Si una falla se para: la fallida queda `failed` y las
 * que dependen de ella (cambios posteriores de la misma entidad, o que referencian algo que creaba) quedan `blocked`.
 */
@Injectable({ providedIn: 'root' })
export class OfflineQueueService {
  private readonly config = inject(RuntimeConfigService);
  private readonly state = inject(AppStateService);
  private readonly injector = inject(Injector);
  private readonly repositories = inject(OFFLINE_REPOSITORIES, { optional: true }) ?? {};
  private readonly db = new OfflineDb(inject(OFFLINE_DB_NAME, { optional: true }) ?? undefined);
  private readonly configured = this.config.value('data.offline');
  private readonly configuredDelay = this.config.value('data.offline-sync-delay');
  private readonly providers = new Map<string, Registered>();
  private readonly appliedSubject = new Subject<OfflineApplied>();
  private readonly scope = signal<string | null>(null);
  private readonly shadows = signal(new Map<string, OfflineShadow>());
  private readonly opsSignal = signal<OfflineOp[]>([]);
  private readonly runSignal = signal(new Map<number, OfflineRunState>());
  private readonly syncSignal = signal<OfflineSyncState>('idle');
  private readonly onlineSignal = signal(typeof navigator === 'undefined' ? true : navigator.onLine);
  private loading: Promise<void> = Promise.resolve();
  private channel?: BroadcastChannel;
  private started = false;
  private warned = false;
  private retryTimer?: ReturnType<typeof setTimeout>;
  private autoTimer?: ReturnType<typeof setTimeout>;
  /** Intentos automáticos seguidos cortados por la red: cada uno dobla la espera del siguiente. */
  private autoAttempts = 0;

  /** Modo offline activo: configurado y con IndexedDB disponible. */
  readonly enabled = computed(() => this.configured() === true && OfflineDb.available());
  /** Operaciones pendientes de la sesión actual, por orden. */
  readonly ops = this.opsSignal.asReadonly();
  readonly pending = computed(() => this.opsSignal().length);
  readonly failed = computed(() => this.opsSignal().filter((op) => op.status === 'failed').length);
  /** El navegador dice que hay red (no garantiza llegar al servidor). */
  readonly online = this.onlineSignal.asReadonly();
  readonly syncState = this.syncSignal.asReadonly();
  /** Estado en memoria de las operaciones de la sincronización en curso. */
  readonly run = this.runSignal.asReadonly();
  /** Espera (ms) con la conexión estable antes de subir sola; `0` desactiva la subida automática. */
  readonly autoSyncDelay = computed(() => {
    const value = Number(this.configuredDelay() ?? DEFAULT_AUTO_SYNC_DELAY);
    return Number.isFinite(value) && value > 0 ? value : 0;
  });
  /** Se dan las condiciones para la subida automática; falta que la conexión se mantenga el tiempo de espera. */
  readonly autoSyncArmed = computed(
    () =>
      this.enabled() &&
      this.autoSyncDelay() > 0 &&
      this.onlineSignal() &&
      this.pending() > 0 &&
      this.failed() === 0 &&
      this.syncSignal() !== 'syncing',
  );
  /** Operaciones subidas: los repositorios afectados refrescan su caché. */
  readonly applied$: Observable<OfflineApplied> = this.appliedSubject.asObservable();

  constructor() {
    effect(() => {
      if (this.enabled()) {
        untracked(() => this.start());
      }
    });
    // Cualquier corte (un fallo de red, el evento `offline`) desarma el temporizador: la espera vuelve a empezar
    effect(() => {
      const armed = this.autoSyncArmed();
      untracked(() => (armed ? this.armAutoSync() : this.disarmAutoSync()));
    });
  }

  /** Envuelve el provider del repositorio; sin modo offline las llamadas pasan tal cual. */
  wrap<T, F>(meta: RepositoryMetadata<T, F>): RepositoryProvider<T, F> {
    const provider = meta.provider;
    if (provider instanceof OfflineProvider) {
      return provider;
    }
    this.providers.set(meta.name, { raw: provider, key: meta.key });
    return new OfflineProvider<T, F>(this, provider, meta.name, meta.key, meta.entity?.display);
  }

  /** Espera a que estén cargadas las operaciones de la sesión actual. */
  ready(): Promise<void> {
    return this.loading;
  }

  /** Las escrituras van a la cola: sin red, o con cambios pendientes (para conservar el orden). */
  shouldQueue(): boolean {
    return !this.onlineSignal() || this.opsSignal().length > 0;
  }

  /** Copia local de una entidad con cambios pendientes. */
  shadow(repo: string, key: string): OfflineShadow | undefined {
    return this.shadows().get(repo + '|' + key);
  }

  /** Claves de las entidades creadas sin conexión en `repo`. */
  created(repo: string): OfflineShadow[] {
    const keys = new Set(
      this.opsSignal()
        .filter((op) => op.repo === repo && op.kind === 'add')
        .map((op) => op.key),
    );
    return [...this.shadows().values()].filter((shadow) => shadow.repo === repo && keys.has(shadow.key));
  }

  /**
   * No se ha llegado al servidor aunque el navegador diga que hay red. Si el navegador no cambia de estado no llega el
   * evento `online`: pasado {@link RETRY_ONLINE} se vuelve a probar con la siguiente petición.
   */
  markOffline(): void {
    this.onlineSignal.set(false);
    clearTimeout(this.retryTimer);
    this.retryTimer = setTimeout(() => this.onlineSignal.set(navigator.onLine), RETRY_ONLINE);
  }

  /**
   * Encola una operación (fusionándola con la anterior de la misma entidad si se puede) y actualiza la copia local.
   * Devuelve el valor local de la entidad tras el cambio.
   */
  async enqueue(op: Omit<OfflineOp, 'scope' | 'status' | 'createdAt'>): Promise<any> {
    await this.ready();
    const scope = this.currentScope();
    const full: OfflineOp = { ...op, scope, status: 'pending', createdAt: Date.now() };
    const shadow = this.shadow(op.repo, op.key);
    if (op.kind !== 'add' && op.kind !== 'file' && full.base === undefined) {
      full.base = shadow?.value ?? (await this.recall(op.repo, 'r', op.key));
    }
    const plan = compact(this.opsSignal(), full);
    await Promise.all(plan.remove.map((seq) => this.db.delete('ops', seq)));
    await Promise.all(plan.replace.map((item) => this.db.put('ops', item)));
    if (plan.append) {
      await this.db.put('ops', plan.append);
    }
    const value = await this.applyShadow(full, shadow, plan.remove.length > 0 && !plan.append);
    await this.reload();
    this.persistStorage();
    if (!this.warned) {
      this.warned = true;
      this.notify().info('offline.notify.queued');
    }
    return value;
  }

  /** Guarda un adjunto en local y encola su subida; devuelve la URL local con la que se referencia. */
  async storeFile(repo: string, endpoint: string, field: string, file: File): Promise<string> {
    await this.ready();
    const id = crypto.randomUUID();
    const scope = this.currentScope();
    await this.db.put('files', { id, scope, blob: file, name: file.name, type: file.type });
    await this.enqueue({ repo, kind: 'file', key: id, endpoint, field, fileName: file.name, label: file.name });
    return OFFLINE_FILE_PREFIX + id;
  }

  /** Adjunto local por su URL `offline-file://…`. */
  async file(url: string): Promise<{ blob: Blob; name: string } | undefined> {
    const record = await this.db.get('files', url.substring(OFFLINE_FILE_PREFIX.length));
    return record ? { blob: record.blob, name: record.name } : undefined;
  }

  /** Guarda la respuesta de una lectura para consultarla sin conexión. */
  remember(repo: string, kind: string, id: string, value: any): void {
    const scope = this.currentScope();
    this.db.put('reads', { id: scope + '|' + repo + '|' + kind + '|' + id, scope, value, at: Date.now() }).catch(() => {
      // Sin espacio o sin permiso: la lectura sin conexión es un extra
    });
  }

  /** Última respuesta guardada de una lectura. */
  async recall(repo: string, kind: string, id: string): Promise<any> {
    try {
      const read = await this.db.get('reads', this.currentScope() + '|' + repo + '|' + kind + '|' + id);
      return read?.value;
    } catch {
      return undefined;
    }
  }

  /** Operaciones que se descartarían junto con `op`: las que dependen de ella. */
  dependents(op: OfflineOp): OfflineOp[] {
    const deps = dependentsOf(this.opsSignal(), [op]);
    return this.opsSignal().filter((item) => deps.has(item.seq!));
  }

  /** Descarta la operación y las que dependen de ella. */
  async discard(op: OfflineOp): Promise<void> {
    const gone = [op, ...this.dependents(op)];
    await Promise.all(gone.map((item) => this.db.delete('ops', item.seq!)));
    await Promise.all(gone.filter((item) => item.kind === 'file').map((item) => this.db.delete('files', item.key)));
    const left = this.opsSignal().filter((item) => !gone.includes(item));
    await this.dropOrphanShadows(left, gone);
    await this.reload();
    gone.forEach((item) => this.appliedSubject.next({ repo: item.repo, key: item.key }));
  }

  /** Sustituye los datos de una operación (corrección de un error o fusión de un conflicto) y la deja pendiente. */
  async edit(op: OfflineOp, payload: any, base?: any): Promise<void> {
    const changed: OfflineOp = { ...op, payload, status: 'pending', error: undefined, blockedBy: undefined };
    if (base !== undefined) {
      changed.base = base;
    }
    await this.db.put('ops', changed);
    const shadow = this.shadow(op.repo, op.key);
    if (shadow && (op.kind === 'add' || op.kind === 'update')) {
      await this.db.put('shadows', { ...shadow, value: payload });
    }
    await this.reload();
  }

  /** Las tres versiones de una operación rechazada por conflicto: la base, la enviada y la del servidor. */
  async conflict(op: OfflineOp): Promise<{ original: any; sent: any; current: any }> {
    const registered = await this.provider(op.repo);
    const current = await firstValueFrom(registered.raw.retrieve(op.key).pipe(timeout(OP_TIMEOUT)));
    return { original: op.base ?? current, sent: op.payload, current };
  }

  /**
   * Sube las operaciones una a una, por orden. Con `retry` vuelve a intentar las fallidas y bloqueadas y para en el
   * primer error; con `skip` deja las fallidas (y lo que depende de ellas) y sigue con el resto. Sin conexión o con la
   * sesión caducada para siempre, dejando la operación pendiente.
   */
  async sync(mode: OfflineSyncMode = 'retry'): Promise<OfflineSyncState> {
    if (this.syncSignal() === 'syncing') {
      return 'syncing';
    }
    const locks = typeof navigator !== 'undefined' ? navigator.locks : undefined;
    if (!locks) {
      return this.doSync(mode);
    }
    // Una sola pestaña sube a la vez
    return locks.request('offline-queue-sync', { ifAvailable: true }, (lock) =>
      lock ? this.doSync(mode) : Promise.resolve(this.syncSignal()),
    );
  }

  /**
   * Programa la subida automática si no lo está: se lanza si la conexión se mantiene durante la espera. Tras intentos
   * cortados por la red la espera se dobla (red intermitente, p. ej. en movimiento), hasta {@link MAX_AUTO_SYNC_DELAY}.
   */
  private armAutoSync(): void {
    if (this.autoTimer) {
      return;
    }
    const delay = Math.min(this.autoSyncDelay() * 2 ** this.autoAttempts, MAX_AUTO_SYNC_DELAY);
    this.autoTimer = setTimeout(() => {
      this.autoTimer = undefined;
      if (this.autoSyncArmed()) {
        this.autoSync();
      }
    }, delay);
  }

  private disarmAutoSync(): void {
    clearTimeout(this.autoTimer);
    this.autoTimer = undefined;
  }

  private async autoSync(): Promise<void> {
    const result = await this.sync('auto');
    if (result === 'offline') {
      this.autoAttempts++;
      return;
    }
    this.autoAttempts = 0;
    if (result === 'done') {
      this.notify().success('offline.notify.synced');
    } else if (result === 'stopped' && this.failed()) {
      this.notify().error('offline.notify.autoFailed', { count: this.failed() });
    }
  }

  /** Limpia el estado de la última sincronización (al cerrar el diálogo). */
  resetRun(): void {
    if (this.syncSignal() !== 'syncing') {
      this.runSignal.set(new Map());
      this.syncSignal.set('idle');
    }
  }

  private async doSync(mode: OfflineSyncMode): Promise<OfflineSyncState> {
    await this.ready();
    this.syncSignal.set('syncing');
    this.runSignal.set(new Map());
    this.onlineSignal.set(true);
    let result: OfflineSyncState = 'done';
    try {
      if (mode === 'retry') {
        // Lo que ya falló solo se reintenta a petición del usuario, nunca en la subida automática
        await this.markAll(
          this.opsSignal().filter((op) => op.status !== 'pending'),
          (op) => ({ ...op, status: 'pending', error: undefined, blockedBy: undefined }),
        );
      }
      await this.blockDependents(this.opsSignal().filter((op) => op.status === 'failed'));
      for (;;) {
        const next = sorted(this.opsSignal()).find((op) => op.status === 'pending');
        if (!next) {
          break;
        }
        this.setRun(next.seq!, 'running');
        try {
          await this.execute(next);
          this.setRun(next.seq!, 'done');
        } catch (error) {
          this.deleteRun(next.seq!);
          if (isNetworkError(error)) {
            this.markOffline();
            if (next.kind === 'add' && !next.uncertain) {
              await this.db.put('ops', { ...next, uncertain: true });
              await this.reload();
            }
            result = 'offline';
            break;
          }
          await this.fail(next, offlineError(error));
          if (mode !== 'skip' || (error as any)?.status === UNAUTHORIZED || (error as any)?.code === UNAUTHORIZED) {
            result = 'stopped';
            break;
          }
        }
      }
      if (result === 'done' && this.opsSignal().length) {
        result = 'stopped';
      }
    } finally {
      if (result === 'done') {
        this.autoAttempts = 0;
      }
      this.syncSignal.set(result);
    }
    return result;
  }

  /** Sube una operación con el provider real y la quita de la cola. */
  private async execute(op: OfflineOp): Promise<void> {
    const { raw } = await this.provider(op.repo);
    const limit = op.kind === 'file' ? FILE_TIMEOUT : OP_TIMEOUT;
    const call = <V>(obs: Observable<V>) => lastValueFrom(obs.pipe(timeout(limit)));
    switch (op.kind) {
      case 'add':
        // Si la red falló con la petición en vuelo, el alta puede estar ya en el servidor
        if (!(op.uncertain && (await this.exists(raw, op.key)))) {
          await call(raw.add(op.payload));
        }
        break;
      case 'update':
        await call(raw.update(op.key, op.payload));
        break;
      case 'patch':
        await call(raw.patch(op.key, op.payload, op.path));
        break;
      case 'delete':
        try {
          await call(raw.delete(op.key));
        } catch (error) {
          // Ya no existe: el borrado está hecho
          if ((error as any)?.status !== NOT_FOUND && (error as any)?.code !== NOT_FOUND) {
            throw error;
          }
        }
        break;
      case 'file':
        await this.uploadFile(op, raw, call);
        break;
    }
    await this.db.delete('ops', op.seq!);
    const left = this.opsSignal().filter((item) => item.seq !== op.seq);
    await this.dropOrphanShadows(left, [op]);
    await this.reload();
    if (op.kind !== 'file') {
      this.appliedSubject.next({ repo: op.repo, key: op.key });
    }
  }

  /** Sube el adjunto y sustituye su URL local por la definitiva en las operaciones y copias locales. */
  private async uploadFile(
    op: OfflineOp,
    raw: RepositoryProvider<any, any>,
    call: <V>(obs: Observable<V>) => Promise<V>,
  ): Promise<void> {
    const record = await this.db.get('files', op.key);
    if (!record) {
      throw new Error('offline.error.missingFile');
    }
    const file = new File([record.blob], record.name, { type: record.type });
    const uploaded = await call(raw.storeFile(op.endpoint!, op.field!, file));
    const url = uploaded?.data;
    if (typeof url !== 'string') {
      throw new Error('offline.error.uploadWithoutUrl');
    }
    const local = OFFLINE_FILE_PREFIX + op.key;
    const ops = this.opsSignal().filter((item) => item.seq !== op.seq);
    await Promise.all(
      ops
        .filter((item) => JSON.stringify(item.payload ?? null).includes(local))
        .map((item) => this.db.put('ops', { ...item, payload: replaceValue(item.payload, local, url) })),
    );
    await Promise.all(
      [...this.shadows().values()]
        .filter((shadow) => JSON.stringify(shadow.value ?? null).includes(local))
        .map((shadow) => this.db.put('shadows', { ...shadow, value: replaceValue(shadow.value, local, url) })),
    );
    await this.db.delete('files', op.key);
  }

  private async exists(raw: RepositoryProvider<any, any>, key: string): Promise<boolean> {
    try {
      await firstValueFrom(raw.retrieve(key).pipe(timeout(OP_TIMEOUT)));
      return true;
    } catch (error) {
      if (isNetworkError(error)) {
        throw error;
      }
      return false;
    }
  }

  /** Marca la operación como fallida y bloquea las que dependen de ella. */
  private async fail(op: OfflineOp, error: OfflineError): Promise<void> {
    const failed: OfflineOp = { ...op, status: 'failed', error, blockedBy: undefined };
    await this.db.put('ops', failed);
    await this.reload();
    await this.blockDependents([failed]);
  }

  private async blockDependents(failed: OfflineOp[]): Promise<void> {
    if (!failed.length) {
      return;
    }
    const deps = dependentsOf(this.opsSignal(), failed);
    await this.markAll(
      this.opsSignal().filter((op) => deps.has(op.seq!) && op.status === 'pending'),
      (op) => ({ ...op, status: 'blocked', blockedBy: deps.get(op.seq!) }),
    );
  }

  private async markAll(ops: OfflineOp[], change: (op: OfflineOp) => OfflineOp): Promise<void> {
    if (ops.length) {
      await Promise.all(ops.map((op) => this.db.put('ops', change(op))));
      await this.reload();
    }
  }

  /** Provider real del repositorio; si no se ha usado en esta sesión, se instancia desde el registro. */
  private async provider(repo: string): Promise<Registered> {
    let registered = this.providers.get(repo);
    if (!registered && this.repositories[repo]) {
      const type = await this.repositories[repo]();
      this.injector.get(type);
      registered = this.providers.get(repo);
    }
    if (!registered) {
      throw new Error('offline.error.noRepository');
    }
    return registered;
  }

  /** Actualiza la copia local de la entidad tras encolar `op`; devuelve su valor. */
  private async applyShadow(op: OfflineOp, shadow: OfflineShadow | undefined, vanished: boolean): Promise<any> {
    if (op.kind === 'file') {
      return undefined;
    }
    const id = op.scope + '|' + op.repo + '|' + op.key;
    if (op.kind === 'delete') {
      if (vanished) {
        // Creada y borrada sin conexión: no llega a existir
        await this.db.delete('shadows', id);
      } else {
        await this.db.put('shadows', { id, scope: op.scope, repo: op.repo, key: op.key, deleted: true });
      }
      return undefined;
    }
    const value = op.kind === 'patch' ? { ...(shadow?.value ?? op.base ?? {}), ...op.payload } : op.payload;
    await this.db.put('shadows', { id, scope: op.scope, repo: op.repo, key: op.key, value });
    return value;
  }

  /** Borra las copias locales de las entidades sin operaciones pendientes: manda el servidor. */
  private async dropOrphanShadows(left: OfflineOp[], gone: OfflineOp[]): Promise<void> {
    const alive = new Set(left.map((op) => entityId(op)));
    const orphans = new Set(gone.map((op) => entityId(op)).filter((id) => !alive.has(id)));
    await Promise.all([...orphans].map((id) => this.db.delete('shadows', this.currentScope() + '|' + id)));
  }

  private setRun(seq: number, value: OfflineRunState) {
    this.runSignal.update((run) => new Map(run).set(seq, value));
  }

  private deleteRun(seq: number) {
    this.runSignal.update((run) => {
      const copy = new Map(run);
      copy.delete(seq);
      return copy;
    });
  }

  private start(): void {
    if (this.started) {
      return;
    }
    this.started = true;
    window.addEventListener('online', () => this.onlineSignal.set(true));
    window.addEventListener('offline', () => this.onlineSignal.set(false));
    if (typeof BroadcastChannel !== 'undefined') {
      this.channel = new BroadcastChannel('offline-queue');
      // Otra pestaña ha cambiado la cola
      this.channel.onmessage = () => this.reload(false);
    }
    this.db.prune(Date.now() - READS_TTL).catch(() => undefined);
    this.scope$().subscribe((scope) => {
      this.scope.set(scope);
      this.loading = this.reload(false);
    });
  }

  /** Usuario de cada identidad y tenant: la cola de una sesión no se mezcla con la de otra. */
  private scope$(): Observable<string> {
    return combineLatest([
      this.state.tenant$,
      this.config.value$('identity').pipe(
        switchMap((identities) => {
          const names = Object.keys(identities ?? {}).sort();
          return names.length
            ? combineLatest(names.map((name) => this.state.user$(name).pipe(map((user) => user?.uid ?? ''))))
            : of([] as string[]);
        }),
      ),
    ]).pipe(
      map(([tenant, users]) => (tenant ?? '') + '|' + users.join(',')),
      distinctUntilChanged(),
    );
  }

  private currentScope(): string {
    return this.scope() ?? '|';
  }

  /** Relee la cola y las copias locales de la sesión; avisa a las demás pestañas si el cambio es propio. */
  private async reload(broadcast = true): Promise<void> {
    const scope = this.currentScope();
    const [ops, shadows] = await Promise.all([this.db.all('ops', scope), this.db.all('shadows', scope)]);
    this.opsSignal.set(sorted(ops));
    this.shadows.set(new Map(shadows.map((shadow) => [entityId(shadow), shadow])));
    if (broadcast) {
      this.channel?.postMessage('changed');
    }
  }

  /** Pide al navegador que no borre la base por falta de espacio o inactividad (Safari la borra a los 7 días). */
  private persistStorage(): void {
    navigator.storage?.persist?.().catch(() => undefined);
  }

  private notify(): NotifyService {
    return this.injector.get(NotifyService);
  }
}
